// navigator.webdriver -> false
Object.defineProperty(Navigator.prototype, 'webdriver', { get: () => false });

// languages cohérentes
Object.defineProperty(Navigator.prototype, 'languages', { get: () => ['fr-FR','fr','en-US','en'] });

// plugins non vide
Object.defineProperty(Navigator.prototype, 'plugins', { get: () => [1,2,3] });

// Chrome runtime stub
window.chrome = window.chrome || { runtime: {} };

// Permissions API: notifications = "default"
const origQuery = navigator.permissions && navigator.permissions.query;
if (origQuery) {
  navigator.permissions.query = (parameters) => (
    parameters && parameters.name === 'notifications'
      ? Promise.resolve({ state: Notification.permission })
      : origQuery(parameters)
  );
}

// WebGL vendor/renderer neutres
(function() {
  const getParameter = WebGLRenderingContext.prototype.getParameter;
  WebGLRenderingContext.prototype.getParameter = function(param){
    if (param === 37445) return 'Intel Inc.';        // UNMASKED_VENDOR_WEBGL
    if (param === 37446) return 'Intel(R) Iris(TM)'; // UNMASKED_RENDERER_WEBGL
    return getParameter.call(this, param);
  };
})();
